                <span className="absolute top-4 left-4 z-10 bg-dark-secondary text-black text-xs font-bold px-2 py-1">
                    {badge}
                </span>
            )}
            <img 
                src={image} 
                alt={name} 
                className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
            />
            <button className="absolute bottom-4 left-4 right-4 bg-white text-black py-3 translate-y-12 group-hover:translate-y-0 transition-transform duration-300 font-bold opacity-0 group-hover:opacity-100">
                ADD TO CART
            </button>
        </div>
        <h3 className="text-lg font-medium">{name}</h3>
        <p className="text-dark-muted text-sm mb-1">{category}</p>
        <p className="font-bold">${price}</p>
    </article>
);

